<?php
 namespace QQWorld\Catalog\Api; use QQWorld\TestFramework\TestCase\WebapiAbstract; class ProductMediaAttributeManagementTest extends WebapiAbstract { public function testGetList() { $attributeSetName = 'attribute_set_with_media_attribute'; $serviceInfo = [ 'rest' => [ 'resourcePath' => '/V1/products/media/types/' . $attributeSetName, 'httpMethod' => \QQWorld\Framework\Webapi\Rest\Request::HTTP_METHOD_GET, ], 'soap' => [ 'service' => 'catalogProductMediaAttributeManagementV1', 'serviceVersion' => 'V1', 'operation' => 'catalogProductMediaAttributeManagementV1GetList', ], ]; $requestData = [ 'attributeSetName' => $attributeSetName, ]; $mediaAttributes = $this->_webApiCall($serviceInfo, $requestData); $this->assertNotEmpty($mediaAttributes); $attribute = $this->getAttributeByCode($mediaAttributes, 'funny_image'); $this->assertNotNull($attribute); $this->assertEquals('Funny image', $attribute['default_frontend_label']); $this->assertEquals(1, $attribute['is_user_defined']); } protected function getAttributeByCode($attributeList, $attributeCode) { foreach ($attributeList as $attribute) { if ($attributeCode == $attribute['attribute_code']) { return $attribute; } } return null; } } 